def weighted_median(data: np.ndarray, weights: np.ndarray) -> int:
    data = np.asarray(data)
    weights = np.asarray(weights)
    if data.size == 0:
        return 0
    sorter = np.argsort(data)
    s_data = data[sorter]
    s_weights = weights[sorter]
    midpoint = 0.5 * s_weights.sum()
    if s_weights.max() > midpoint:
        return int(s_data[s_weights.argmax()])
    cumulative = np.cumsum(s_weights)
    idx = np.where(cumulative <= midpoint)[0][-1] if np.any(cumulative <= midpoint) else 0
    if cumulative[idx] == midpoint and idx + 1 < len(s_data):
        return int(np.mean(s_data[idx : idx + 2]))
    return int(s_data[min(idx + 1, len(s_data) - 1)])


def column_imbalance_score(value_counts: pd.Series, n_classes: int) -> float:
    if n_classes <= 1:
        return 0.0
    probabilities = value_counts / value_counts.sum()
    entropy = stats.entropy(probabilities, base=2)
    max_entropy = np.log2(n_classes)
    return float(1 - (entropy / max_entropy))


