def identify_gaps(gap: pd.Series, is_datetime: bool, gap_tolerance: int = 2) -> Tuple[pd.Series, list]:
    diffs = gap.diff().dropna()
    if diffs.empty:
        return pd.Series(dtype="float64"), []
    non_zero = diffs[diffs != (pd.Timedelta(0) if is_datetime else 0)]
    if non_zero.empty:
        return pd.Series(dtype="float64"), []
    mean_gap = non_zero.mean()
    minimum = mean_gap * gap_tolerance
    large = non_zero[non_zero > minimum]
    anchors = [(gap.index[idx - 1], gap.index[idx]) for idx in range(1, len(gap)) if gap.iloc[idx] - gap.iloc[idx - 1] > minimum]
    return large, anchors


def compute_gap_stats(series: pd.Series) -> pd.Series:
    data = series.dropna()
    if isinstance(data.index, pd.DatetimeIndex):
        gaps, _ = identify_gaps(data.index.to_series(), True)
        return gaps
    return pd.Series(dtype="float64")


def stationarity_test(config: Settings, series: pd.Series) -> Tuple[bool, float]:
    clean = series.dropna()
    if len(clean) < 3:
        return True, 1.0
    try:
        result = adfuller(clean, autolag=config.vars.timeseries.autolag, maxlag=config.vars.timeseries.maxlag)
        pvalue = float(result[1])
        return pvalue < config.vars.timeseries.significance, pvalue
    except Exception:
        return True, 1.0


def fftfreq(n: int, d: float = 1.0) -> np.ndarray:
    return np.fft.fftfreq(n, d=d)


def get_fft(series: pd.Series) -> pd.DataFrame:
    values = np.asarray(series.dropna(), dtype=float)
    if values.size == 0:
        return pd.DataFrame(columns=["freq", "ampl"])
    fft_values = np.fft.fft(values)
    psd = np.abs(fft_values) ** 2
    freqs = np.fft.fftfreq(len(psd), 1.0)
    mask = freqs > 0
    ampl = 10 * np.log10(np.maximum(psd[mask], 1e-12))
    return pd.DataFrame({"freq": freqs[mask], "ampl": ampl})


def get_fft_peaks(fft: pd.DataFrame, mad_threshold: float = 6.0) -> Tuple[float, pd.DataFrame, pd.DataFrame]:
    if fft.empty:
        return 0.0, fft, fft
    median = float(np.median(fft["ampl"]))
    mad_value = float(np.median(np.abs(fft["ampl"] - median)))
    threshold = median + mad_threshold * mad_value
    indices, _ = signal.find_peaks(fft["ampl"].to_numpy())
    peaks = fft.iloc[indices]
    selected = peaks[peaks["ampl"] >= threshold]
    selected = selected.sort_values("ampl", ascending=False).drop_duplicates(subset=["freq"])
    return threshold, peaks, selected


def seasonality_test(series: pd.Series, mad_threshold: float = 6.0) -> Dict[str, Any]:
    fft = get_fft(series)
    _, peaks, selected = get_fft_peaks(fft, mad_threshold=mad_threshold)
    seasonalities = []
    for freq in selected["freq"]:
        if freq != 0:
            seasonalities.append(float(1 / freq))
    return {
        "seasonality_presence": bool(len(selected)),
        "seasonalities": seasonalities,
        "fft": fft,
        "fft_peaks": peaks,
        "fft_selected_peaks": selected,
    }


