def decode_byte_exif(exif_val: str | bytes) -> str:
    return exif_val.decode("utf-8", errors="ignore") if isinstance(exif_val, bytes) else str(exif_val)


def extract_exif(image: PILImage.Image) -> dict:
    try:
        raw = image.getexif() or {}
        return {str(key): decode_byte_exif(value) for key, value in raw.items()}
    except Exception:
