def count_duplicate_hashes(image_descriptions: dict) -> int:
    hashes = [info.get("hash") for info in image_descriptions.values() if info.get("hash")]
    counts = Counter(hashes)
    return sum(count - 1 for count in counts.values() if count > 1)


def extract_exif_series(image_exifs: list) -> dict:
    key_counter = Counter()
    per_key = {}
    for exif in image_exifs:
        for key, value in exif.items():
            key_counter[key] += 1
            per_key.setdefault(key, Counter())[value] += 1
    return {
        "exif_keys": counter_to_series(key_counter),
        "exif_data": {key: counter_to_series(counter) for key, counter in per_key.items()},
    }


def extract_image_information(path: Path, exif: bool = False, hash: bool = False) -> dict:
    image = open_image(path)
    if image is None:
        return {}
    info = {
        "shape": get_image_shape(image),
        "truncated": is_image_truncated(image),
    }
    if exif:
        info["exif"] = extract_exif(image)
    if hash:
        info["hash"] = hash_image(image)
    return info


def image_summary(series: pd.Series, exif: bool = False, hash: bool = False) -> dict:
    descriptions = {
        str(path): extract_image_information(Path(path), exif=exif, hash=hash)
        for path in series.astype(str)
        if Path(path).exists()
    }
    shapes = pd.Series([info["shape"] for info in descriptions.values() if info.get("shape")], dtype="object")
    exifs = [info.get("exif", {}) for info in descriptions.values()]
    return {
        "image_dimensions": shapes,
        "n_truncated_images": int(sum(1 for info in descriptions.values() if info.get("truncated"))),
        "n_duplicate_hashes": count_duplicate_hashes(descriptions) if hash else 0,
        **extract_exif_series(exifs) if exif else {},
    }


