@get_duplicates.register
def pandas_get_duplicates(config: Settings, df: pd.DataFrame, supported_columns: list):
    if not config.duplicates or not supported_columns:
        return {"n_duplicates": 0, "p_duplicates": 0.0}, None
    duplicated = int(df.duplicated(subset=supported_columns).sum())
    grouped = (
        df.groupby(supported_columns, dropna=False)
        .size()
        .reset_index(name=config.duplicates.key)
        .sort_values(config.duplicates.key, ascending=False)
    )
    grouped = grouped[grouped[config.duplicates.key] > 1].head(config.duplicates.head)
    return {"n_duplicates": duplicated, "p_duplicates": duplicated / max(len(df), 1)}, grouped if not grouped.empty else None


