def cramers_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    categoricals = [column for column, info in summary.items() if info.get("type") in {"Categorical", "Boolean", "Text"}]
    if len(categoricals) < 2:
        return None
    matrix = pd.DataFrame(index=categoricals, columns=categoricals, dtype=float)
    for left in categoricals:
        for right in categoricals:
            matrix.loc[left, right] = 1.0 if left == right else _pairwise_cramers(df[left].astype(str), df[right].astype(str))
    return matrix


